window.RI2_UNITS = {"6":{"unit":6,"code":"RI2-U06","title":"REEF ENCOUNTERS","startNumber":137,"endNumber":162,"entries":[{"number":137,"term":"encounter ~ meet","sourceTerm":"encounter (v) ~ meet (v)","spoken":"encounter , meet","ipa":"encounter /ɪˈnkaʊntɚ/ · meet /miːt/","type":"verb · verb","meaning":"gặp, gặp phải","definition":"To come across a person, animal, or situation; encounter often suggests an unexpected meeting.","note":"encounter + danh từ, không cần giới từ with; encounter thường trang trọng hơn meet.","example":"The researchers met local divers before unexpectedly encountering a rare shark."},{"number":138,"term":"coral reef","sourceTerm":"coral reef","spoken":"coral reef","ipa":"coral /ˈkɔːrəl/ · reef /riːf/","type":"word / phrase","meaning":"rạn san hô","definition":"A large underwater structure formed by the hard remains of tiny sea animals.","note":"","example":"The coral reef provides food and shelter for many marine species."},{"number":139,"term":"construct ~ build","sourceTerm":"construct (v) ~ build (v)","spoken":"construct , build","ipa":"construct /kəˈnstrʌkt/ · build /bɪld/","type":"verb · verb","meaning":"xây dựng","definition":"To build or create something by putting parts together.","note":"construct trang trọng hơn build và thường dùng cho công trình hoặc cấu trúc.","example":"Tiny coral animals construct, or build, hard structures that gradually form a reef."},{"number":140,"term":"remarkable","sourceTerm":"remarkable (a)","spoken":"remarkable","ipa":"remarkable /rɪˈmɑːrkəbəl/","type":"adjective","meaning":"nổi bật, đáng chú ý","definition":"Unusual or impressive enough to deserve attention.","note":"remarkable nhấn mạnh mức độ rất đáng chú ý và thường thể hiện sự đánh giá tích cực.","example":"The reef made a remarkable recovery after fishing was restricted."},{"number":141,"term":"shallow >< deep","sourceTerm":"shallow >< deep","spoken":"shallow , deep","ipa":"shallow /ˈʃæloʊ/ · deep /diːp/","type":"adjective · adjective","meaning":"nông, không sâu · sâu","definition":"Shallow water has little depth; deep water extends far down.","note":"","example":"Young fish remain in shallow water before moving into the deeper reef."},{"number":142,"term":"occupy ~ make up ~ account for","sourceTerm":"occupy ~ make up ~ account for","spoken":"occupy , make up , account for","ipa":"occupy /ˈɑːkjəˌpaɪ/ · make /meɪk/ · up /ʌp/ · account /əˈkaʊnt/","type":"verb · phrasal verb · phrasal verb","meaning":"chiếm không gian hoặc vị trí ~ chiếm, tạo thành một tỉ lệ","definition":"To fill a space or account for a particular share of a total.","note":"occupy thường nói về không gian/vị trí; make up hoặc account for tự nhiên hơn khi nói tỉ lệ.","example":"Coral reefs occupy a small area and make up less than one percent of the ocean, yet they account for rich marine diversity."},{"number":143,"term":"percent · percentage","sourceTerm":"percent · percentage","spoken":"percent , percentage","ipa":"percent /pɚˈsɛnt/ · percentage /pɚˈsɛntədʒ/","type":"noun","meaning":"phần trăm (đứng sau một con số) · tỉ lệ phần trăm","definition":"Percent follows a number to express a share out of one hundred; percentage names that share without giving the figure directly.","note":"20 percent, nhưng a high/low percentage; không dùng a high percent trong văn viết chuẩn.","example":"Only one percent of the area was damaged, so the percentage was lower than expected."},{"number":144,"term":"resident ~ inhabitant","sourceTerm":"resident (n) ~ inhabitant (n)","spoken":"resident , inhabitant","ipa":"resident /ˈrɛzɪdənt/ · inhabitant /ɪˈnhæbətənt/","type":"noun · noun","meaning":"người dân, cư dân","definition":"A person or animal that lives in a particular place.","note":"resident dùng cho người hoặc động vật và nhấn mạnh nơi cư trú; inhabitant là người/động vật sống tại một nơi.","example":"Many reef residents are small fish, while the island's human inhabitants depend on fishing."},{"number":145,"term":"release ~ discharge","sourceTerm":"release (v) ~ discharge (v)","spoken":"release , discharge","ipa":"release /riˈliːs/ · discharge /dɪˈstʃɑːrdʒ/","type":"verb · verb","meaning":"thải, xả (khí, nước thải…)","definition":"To allow a substance such as gas, liquid, or waste to flow out.","note":"discharge thường dùng với nước thải/chất thải; release có phạm vi rộng hơn.","example":"The factory must not discharge wastewater or release harmful chemicals near the reef."},{"number":146,"term":"conserve · conservation · conservationist ~ preserve","sourceTerm":"conserve · conservation · conservationist ~ preserve","spoken":"conserve , conservation , conservationist , preserve","ipa":"conserve /kəˈnsɝːv/ · conservation /ˌkɑːnsɚˈveɪʃən/ · conservationist /ˌkɑːnsɚˈveɪʃənɪst/ · preserve /prəˈzɝːv/","type":"verb · verb · noun · noun","meaning":"bảo tồn, tiết kiệm tài nguyên · sự bảo tồn · người hoạt động bảo tồn ~ gìn giữ nguyên trạng","definition":"To conserve is to protect a resource from loss; to preserve is to keep something in its existing state, while conservation is protective work led by people such as conservationists.","note":"conserve nhấn mạnh bảo vệ tài nguyên; preserve thường nhấn mạnh giữ nguyên trạng.","example":"A conservationist conserved reef resources and preserved coral samples for future study."},{"number":147,"term":"stun · stunned · stunning","sourceTerm":"stun · stunned · stunning","spoken":"stun , stunned , stunning","ipa":"stun /stʌn/ · stunned /stʌnd/ · stunning /ˈstʌnɪŋ/","type":"verb · adjective · adjective","meaning":"làm choáng, làm sững sờ · cảm thấy sững sờ · gây ấn tượng mạnh, tuyệt đẹp","definition":"To stun is to shock or surprise greatly; stunned describes the person's feeling, while stunning describes what causes it.","note":"stunned mô tả cảm xúc của người; stunning mô tả sự vật gây ấn tượng.","example":"The sudden sight of a huge shark stunned the divers, but the underwater view was stunning."},{"number":148,"term":"consequence · consequently ~ therefore","sourceTerm":"consequence · consequently ~ therefore","spoken":"consequence , consequently , therefore","ipa":"consequence /ˈkɑːnsəkwəns/ · consequently /ˈkɑːnsəkwəntli/ · therefore /ˈðɛˌrfɔːr/","type":"noun · adverb · adverb","meaning":"hậu quả, kết quả · do đó, vì vậy","definition":"A consequence is a result, often an unwanted one; consequently and therefore introduce a result.","note":"consequence of + danh từ; consequently/therefore thường dùng trong văn viết trang trọng.","example":"Water temperatures rose; consequently, the reef lost much of its colour."},{"number":149,"term":"horror · horrible ~ horrific","sourceTerm":"horror · horrible ~ horrific","spoken":"horror , horrible , horrific","ipa":"horror /ˈhɔːrɚ/ · horrible /ˈhɔːrəbəl/ · horrific /hɔˈrɪfɪk/","type":"noun · adjective · adjective","meaning":"nỗi hoặc sự kinh hoàng · kinh khủng, gây kinh hoàng","definition":"Horror is a strong feeling of fear or shock; horrible means very unpleasant, while horrific more strongly suggests shocking harm.","note":"to someone's horror mang nghĩa khiến ai kinh hoàng; horrific thường nhấn mạnh điều gây sốc, kinh hoàng.","example":"To their horror, researchers found horrible waste and recorded its horrific effects on wildlife."},{"number":150,"term":"victim","sourceTerm":"victim (n)","spoken":"victim","ipa":"victim /ˈvɪktəm/","type":"noun","meaning":"nạn nhân","definition":"A person, animal, or thing harmed by an event or action.","note":"a victim of + tai nạn/tội phạm/vấn đề.","example":"Sea turtles are often victims of plastic pollution."},{"number":151,"term":"accurate ~ precise","sourceTerm":"accurate ~ precise","spoken":"accurate , precise","ipa":"accurate /ˈækjɚət/ · precise /prɪˈsaɪs/","type":"adjective · adjective","meaning":"đúng với thực tế ~ chính xác đến từng chi tiết, cụ thể","definition":"Accurate information is correct; precise information or measurement is exact and highly detailed.","note":"accurate mô tả thông tin/kết quả đúng; precise nhấn mạnh mức độ chi tiết và độ đo chính xác.","example":"Accurate results depend on precise measurements taken with reliable equipment."},{"number":152,"term":"tempt someone to do something · tempting · temptation","sourceTerm":"tempt someone to do something · tempting · temptation","spoken":"tempt someone to do something , tempting , temptation","ipa":"tempt /tɛmpt/ · someone /ˈsʌˌmwʌn/ · something /ˈsʌmθɪŋ/ · tempting /ˈtɛmptɪŋ/ · temptation /tɛˈmteɪʃən/","type":"verb · noun · adjective · phrase / pattern","meaning":"dụ dỗ ai làm gì · hấp dẫn, khó cưỡng · sự cám dỗ","definition":"To tempt is to make someone want to do something; tempting describes what attracts them, and temptation is that desire.","note":"tempt someone to V; be tempted to V; resist temptation.","example":"Clear water may tempt visitors to touch the coral, but they should resist the temptation."},{"number":153,"term":"approach","sourceTerm":"approach (v) · (n)","spoken":"approach","ipa":"approach /əˈproʊtʃ/","type":"verb · noun","meaning":"đến gần, tiếp cận · cách tiếp cận, phương pháp","definition":"To approach is to move nearer; an approach is a way of dealing with a task or problem.","note":"approach + người/nơi, không dùng approach to khi là động từ; an approach to + danh từ/V-ing.","example":"The team approached the reef carefully and used a low-impact approach to collect data."},{"number":154,"term":"force someone to do something · force","sourceTerm":"force someone to do something · force","spoken":"force someone to do something , force","ipa":"force /fɔːrs/ · someone /ˈsʌˌmwʌn/ · something /ˈsʌmθɪŋ/","type":"verb · noun · phrase / pattern","meaning":"ép ai làm gì · lực; sức ép","definition":"To force someone is to make them act against their choice; force is physical power or strong influence.","note":"force someone to V; be forced to V.","example":"Strong waves forced the divers to return, and the force of the water damaged their equipment."},{"number":155,"term":"curious","sourceTerm":"curious (a)","spoken":"curious","ipa":"curious /ˈkjʊriəs/","type":"adjective","meaning":"tò mò","definition":"Wanting to know, learn, or understand something.","note":"be curious about + danh từ; be curious to know/see.","example":"Curious visitors asked how coral animals build an entire reef."},{"number":156,"term":"state · statement","sourceTerm":"state · statement","spoken":"state , statement","ipa":"state /steɪt/ · statement /ˈsteɪtmənt/","type":"verb · noun","meaning":"nêu rõ, tuyên bố chính thức · lời tuyên bố; bản trình bày","definition":"To state is to express something clearly and formally; a statement is what is said or written.","note":"state that + mệnh đề; statement about/on + vấn đề.","example":"The report states that the reef is recovering, but its final statement calls for continued protection."},{"number":157,"term":"speculate · speculation ~ predict","sourceTerm":"speculate · speculation ~ predict","spoken":"speculate , speculation , predict","ipa":"speculate /ˈspɛkjəˌleɪt/ · speculation /ˌspɛkjəˈleɪʃən/ · predict /prɪˈdɪkt/","type":"verb · verb · noun","meaning":"phỏng đoán khi chưa đủ bằng chứng · sự phỏng đoán ~ dự đoán điều sẽ xảy ra","definition":"To speculate is to suggest an idea without enough evidence, and speculation is such an idea; to predict is to say what is likely to happen.","note":"speculate about/on + vấn đề; khác predict ở chỗ nhấn mạnh thiếu bằng chứng chắc chắn.","example":"Scientists would not speculate about the cause, but reliable data helped them predict how the reef might change."},{"number":158,"term":"yet ~ but","sourceTerm":"yet ~ but","spoken":"yet , but","ipa":"yet /jɛt/ · but /bʌt/","type":"conjunction · conjunction","meaning":"nhưng, tuy nhiên","definition":"Used to introduce an idea that contrasts with what came before.","note":"yet trang trọng và nhấn mạnh sự tương phản bất ngờ hơn but.","example":"The reef covers a small area, yet it supports thousands of species."},{"number":159,"term":"indeed ~ really","sourceTerm":"indeed ~ really","spoken":"indeed , really","ipa":"indeed /ˌɪˈndiːd/ · really /ˈrɪli/","type":"adverb · adverb","meaning":"thực sự; quả thật","definition":"Used to emphasize that a statement is true or to strengthen a previous point.","note":"indeed thường dùng trong văn viết để nhấn mạnh/xác nhận; really thông dụng hơn trong hội thoại.","example":"The reef is highly diverse; indeed, it supports more species than many forests."},{"number":160,"term":"significant","sourceTerm":"significant (a)","spoken":"significant","ipa":"significant /səˈɡnɪfɪkənt/","type":"adjective","meaning":"quan trọng; to lớn, đáng kể","definition":"Important, noticeable, or large enough to have an effect.","note":"significant change/difference/effect; trong nghiên cứu còn có nghĩa “có ý nghĩa thống kê”.","example":"Even a small rise in temperature can cause significant damage to coral."},{"number":161,"term":"scale · on a ... scale","sourceTerm":"scale · on a ... scale","spoken":"scale , on a ... scale","ipa":"scale /skeɪl/","type":"noun","meaning":"quy mô, mức độ · trên một quy mô nào đó","definition":"The size or extent of an activity, event, or problem.","note":"on a large/small/global scale.","example":"Protecting reefs on a global scale requires cooperation between many countries."},{"number":162,"term":"fiction · science fiction","sourceTerm":"fiction · science fiction","spoken":"fiction , science fiction","ipa":"fiction /ˈfɪkʃən/ · science /ˈsaɪəns/","type":"noun","meaning":"văn học hoặc tác phẩm hư cấu · khoa học viễn tưởng","definition":"Fiction is literature based on imagined events; science fiction explores imagined science or technology.","note":"fiction là danh từ không đếm được khi chỉ thể loại; a work of fiction chỉ một tác phẩm hư cấu.","example":"The enormous sea creature belongs in science fiction, not in a factual reef survey."}],"pronunciationFocus":[{"entryNumber":139,"points":[{"category":"word-stress","note":"construct trong nghĩa xây dựng nhấn âm tiết thứ hai"},{"category":"final-sound","note":"construct kết thúc bằng cụm /kt/"}]},{"entryNumber":142,"points":[{"category":"linking","note":"Đọc liền make‿up, nối /k/ cuối make sang nguyên âm /ʌ/ của up"}]},{"entryNumber":145,"points":[{"category":"final-sound","note":"release kết thúc bằng /s/; discharge kết thúc bằng /dʒ/"}]},{"entryNumber":146,"points":[{"category":"word-stress","note":"conserve và preserve nhấn âm tiết thứ hai; conservation chuyển trọng âm sang âm tiết chứa /eɪ/"}]},{"entryNumber":147,"points":[{"category":"final-sound","note":"stunned kết thúc bằng cụm /nd/; giữ rõ /d/"}]},{"entryNumber":152,"points":[{"category":"word-stress","note":"tempting nhấn âm đầu; temptation chuyển trọng âm sang âm tiết chứa /teɪ/"},{"category":"final-sound","note":"tempt kết thúc bằng cụm /mpt/"}]},{"entryNumber":157,"points":[{"category":"word-stress","note":"speculate nhấn âm đầu; speculation chuyển trọng âm sang âm tiết chứa /eɪ/"},{"category":"final-sound","note":"predict kết thúc bằng cụm /kt/"}]}]}};
